      "evidence": ["esptool/targets/", "esptool/targets/stub_flasher/"]
    }
  ],
  "domain": "嵌入式开发工具 / 固件烧录与 provisioning（embedded tooling）",
  "target_users": "嵌入式/IoT 固件开发者、ESP-IDF 构建系统、产线烧录与测试脚本",
